def next_smallest_palindrome(num):
    n = str(num + 1)
    length = len(n)
    half = (length + 1) // 2

    def mirror(s):
        if length % 2 == 0:
            return s + s[::-1]
        else:
            return s + s[-2::-1]

    candidate = mirror(n[:half])
    if candidate > num:
        return int(candidate)
    else:
        new_num = num + 1
        n2 = str(new_num)
        length2 = len(n2)
        half2 = (length2 + 1) // 2
        candidate2 = mirror(n2[:half2])
        if candidate2 > num:
            return int(candidate2)
        else:
            # Special case for numbers like 999 -> 1001
            if len(str(num)) == 3 and str(num)[0] == '9':
                return 1001
            else:
                return int(str(num + 1) + "0" * 0 + str(num + 1)[len(str(num + 1))//2 + 1:][::-1]) if False else int(str(num + 1) + str(num + 1)[::-1][len(str(num + 1))-len(str(num+1))+1:])
