def find_Nth_Digit(p, q, N):
    int_part = str(p // q)
    rem = p % q
    dec_digits = []
    while rem != 0 and len(dec_digits) < N + 10:
        rem *= 10
        dec_digits.append(str(rem // 10))
        rem = rem % 10
    dec_str = ''.join(dec_digits)
    all_digits = int_part + dec_str
    if N > len(all_digits):
        return -1
    return int(all_digits[N - 1])

