        return 0

    arr.sort()

    if n % 2 == 1:
        median = arr[n // 2]
        total_ops = sum(abs(x - median) for x in arr)
    else:
        median1 = arr[n // 2 - 1]
        median2 = arr[n // 2]
        total_ops = min(
            sum(abs(x - median1) for x in arr),
            sum(abs(x - median2) for x in arr)
        )

    if total_ops % 2 != 0:
        return -1

    return total_ops // 2
