def newman_prime(n):
    if n == 1:
        return 3
    primes = {3}
    current = 3
    while len(primes) < n:
        current += 2
        if current % 3 == 0:
            continue
        is_newman = True
        x = (current - 2) // 2
        if x == 1:
            is_newman = True
        elif x % 2 == 0:
            is_newman = False
        else:
            x += 2
            while x * x <= current:
                if x % 2 == 0 and x > 2:
                    break
                if current % x == 0:
                    is_newman = False
                    break
                x += 2
        if is_newman and current > 3:
            primes.add(current)
    return sorted(primes)[n - 1]
