import math

def prod_Square(n):
    if n < 0:
        return False
    if n == 0 or n == 1:
        return False
    if n < 0:
        return False
    # Check if n can be expressed as (a^2) * (b^2)
    # n must be positive and not a perfect square of a prime
    # Actually, n can be a product of two squares if and only if
    # n is not square-free and n is not a perfect square of a prime.
    # Simpler: iterate over possible square roots a and b
    limit = int(math.isqrt(n))
    for a in range(1, limit + 1):
        a_sq = a * a
        if a_sq > n:
            break
        b_sq = n // a_sq
        if a_sq * b_sq == n and math.isqrt(b_sq) ** 2 == b_sq:
            # b_sq must be a perfect square
            b = int(math.isqrt(b_sq))
            if b * b == b_sq:
                # Check that a and b are positive integers
                if a > 0 and b > 0:
                    return True
    return False
