def bell_Number(n):
    bell_cache = {0: 1, 1: 1}

    def bell_rec(k):
        if k in bell_cache:
            return bell_cache[k]
        total = 0
        for i in range(k):
            total += bell_rec(i) * bell_rec(k - 1 - i)
        bell_cache[k] = total
        return total

    if n == 0 or n == 1:
        return 1
    return bell_rec(n)
