def find_rotation_count(A):
    n = len(A)
    if n == 0 or n == 1:
        return 0

    low, high = 0, n - 1

    # If array is already sorted
    if A[low] <= A[high]:
        return 0

    while low <= high:
        mid = (low + high) // 2

        # Check if mid is the pivot
        if A[mid] > A[mid + 1]:
            return mid + 1
        elif A[mid] < A[mid - 1]:
            return mid

        # Decide which half to search
        if A[low] <= A[mid]:
            low = mid + 1
        else:
            high = mid - 1

    # Fallback: linear search for small arrays
    for i in range(1, n):
        if A[i] < A[i - 1]:
            return i

    return 0

