def newman_prime(n):
    primes = [2, 2, 5]
    while len(primes) <= n:
        count = 0
        for i in range(len(primes)):
            for j in range(i, len(primes)):
                candidate = primes[i] + primes[j] + 2
                is_prime = True
                for k in range(2, int(candidate ** 0.5) + 1):
                    if candidate % k == 0:
                        is_prime = False
                        break
                if is_prime and candidate not in primes:
                    primes.append(candidate)
                    count += 1
