def Check_Solution(a, b, c):
    if a == 0:
        return "No"

    d = b**2 - 4*a*c
    if d < 0:
        return "No"

    sqrt_d = math.sqrt(d)
    r1 = (-b + sqrt_d) / (2*a)
    r2 = (-b - sqrt_d) / (2*a)

    if r1 * r2 == 1:
        return "Yes"
    elif r1 * r2 == 0 or r1 == 0 or r2 == 0:
        return "No"
    else:
        return "No"
```

