def count_Odd_Squares(n, m):
    def has_odd_factor(x):
        if x <= 1:
            return False
        odd = x
        while odd * odd <= x:
            if x % odd == 0:
                if odd % 2 == 1:
                    return True
                other = x // odd
                if other % 2 == 1:
                    return True
            odd += 1
        return False

    count = 0
    for x in range(n, m + 1):
        if has_odd_factor(x):
            count += 1
    return count

