import re

def find_adverbs(text):
    pattern = re.compile(r'\b\d*\b|\b[A-Za-z]+\b', re.IGNORECASE)
    words = re.findall(r'\b[A-Za-z]+\b', text)

    # Get character positions for each word
    positions = {}
    idx = 0
    for word in words:
        start = idx
        end = idx + len(word)
        positions[word.lower()] = (start, end)
        idx = end + 1  # +1 for space

    adverbs = re.findall(r'\badverbs?\b', text, re.IGNORECASE)

    results = []
    for adv in adverbs:
        adv_lower = adv.lower()
        found = False
        for word, (start, end) in positions.items():
            if word == adv_lower and len(word) > 2 and word not in ['the', 'and', 'for', 'not', 'but', 'was', 'his', 'her', 'all', 'any', 'can', 'did', 'get', 'had', 'has', 'have', 'she', 'him', 'they', 'you']:
                # Check if it ends with 'ly'
                if word.endswith('ly') and len(word) >= 3:
                    results.append(f"{start}-{end}: {adv}")
                    found = True
                    break
    return ', '.join(results)

