def find_Points(l1, r1, l2, r2):
    intervals = [(l1, r1), (l2, r2)]
    intervals.sort()

    merged = []
    for l, r in intervals:
        if not merged or l > merged[-1][1] + 1:
            merged.append([l, r])
        else:
            merged[-1][1] = max(merged[-1][1], r)

    result = []
    for l, r in merged:
        if l1 <= l and r1 >= r and not (l2 <= l and r2 >= r):
            result.append((l, r))
        elif l2 <= l and r2 >= r and not (l1 <= l and r1 >= r):
            result.append((l, r))

    return result[0] if result else (0, 0)
