def permute_string(str):
    def backtrack(path, remaining, result):
        if not remaining:
            result.append(''.join(path))
            return
        seen = set()
        for i, ch in enumerate(remaining):
            if ch in seen:
                continue
            seen.add(ch)
            backtrack(path + [ch], remaining[:i] + remaining[i+1:], result)

    result = []
    backtrack([], str, result)
    return result
```

