def permute_string(s):
    def backtrack(path, remaining):
        if not remaining:
            result.append("".join(path))
            return
        seen = set()
        for i in range(len(remaining)):
            if remaining[i] in seen:
                continue
            seen.add(remaining[i])
            backtrack(
                path + [remaining[i]],
                remaining[:i] + remaining[i+1:]
            )

    backtrack([], sorted(s))
    return result
