def no_of_subsequences(arr, k):
    arr = [x for x in arr if x > 0]
    arr.sort()
    n = len(arr)
    if n == 0:
        return 1 if k > 1 else 0

    prefix = [1]
    for x in arr:
        prefix.append(prefix[-1] * x)

    total = 0
    seen = {}

    def dfs(start, prod, cnt):
        nonlocal total
        if cnt > 0:
            total += cnt

        for i in range(start, n):
            if prod * arr[i] >= k and prod > 0:
                break
            dfs(i + 1, prod * arr[i], cnt + 1)

    # Count subsequences of all lengths using DP over product
    dp = {}
    for x in arr:
        new_dp = {}
        for p, c in list(dp.items()):
            np = p * x
            if np < k:
                new_dp[np] = new_dp.get(np, 0) + c
        if x < k:
            new_dp[x] = new_dp.get(x, 0) + 1
        for p, c in new_dp.items():
            dp[p] = dp.get(p, 0) + c
        if x < k and x not in dp:
            dp[x] = dp.get(x, 0) + 1

    # Count all subsequences (including empty handled separately)
    total = 0
    dp_map = {}
    for x in arr:
        if x >= k:
            continue
        # count subsequences ending with x
        new = {}
        for p, c in list(dp_map.items()):
            np = p * x
            if np < k:
                new[np] = new.get(np, 0) + c
        new[x] = new.get(x, 0) + 1
        for p, c in new.items():
            dp_map[p] = dp_map.get(p, 0) + c

    total = sum(dp_map.values())
    total += 1  # empty subsequence
    return total
