def no_of_subsequences(arr, k):
    n = len(arr)
    if n == 0 or k <= 1:
        return 0

    count = 0

    def dfs(idx, prod):
        nonlocal count
        if idx == n:
            if prod < k and prod != 1:
                count += 1
            return

        # Exclude current element
        dfs(idx + 1, prod)

        # Include current element
        new_prod = prod * arr[idx]
        if new_prod < k:
            dfs(idx + 1, new_prod)
        elif new_prod == 1 and arr[idx] == 1:
            dfs(idx + 1, 1)

    dfs(0, 1)

    # Subtract empty subsequence if it was counted (prod=1, arr elements all 1)
    # The empty subsequence has product 1, which is < k for k > 1
    # We need to subtract it if it got counted
    # Better: start counting from non-empty by handling first element separately

    # Reset and do a clean count for non-empty subsequences
    count = 0
    for mask in range(1, (1 << n) - 1):
        prod = 1
        for i in range(n):
            if mask & (1 << i):
                prod *= arr[i]
        if prod < k:
            count += 1

    return count
