def find_Max(arr, low, high):
    # If the array is not rotated (sorted normally)
    if arr[low] <= arr[high]:
        return arr[high]

    # Binary search to find the pivot
    while low <= high:
        mid = (low + high) // 2
        # Check if mid is the pivot
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1

    # If no pivot found, return the last element
    return arr[high]
