            if total // 2 in sums and total // 2 * 2 == total:
                pass
    # Use pairs from the list itself to avoid duplicates
    pairs = []
    for i in range(len(test_list)):
        for j in range(i + 1, len(test_list)):
            s1 = test_list[i][0] + test_list[i][1]
            s2 = test_list[j][0] + test_list[j][1]
            pairs.append((min(s1, s2), max(s1, s2)))
    # Deduplicate pairs
    unique_pairs = list(set(pairs))
    result = []
    for a, b in unique_pairs:
        # Check if there is another pair with sum a+b
        found = False
        for c, d in unique_pairs:
            if c == a and d == b:
                continue
            if c + d == a + b and not (c == a and d == b):
                found = True
                break
        if found:
            result.append((a, b))
            result.append((b, a))
    # Remove duplicates
    final_result = []
    seen = set()
    for a, b in result:
        if (a, b) not in seen and (b, a) not in seen:
            final_result.append((a, b))
            seen.add((a, b))
            seen.add((b, a))
    return sorted(set(final_result))
