def max_product(arr):
    if len(arr) < 2:
        return None if not arr else (arr[0], arr[0])

    positives = sorted([x for x in arr if x > 0], reverse=True)
    negatives = sorted([x for x in arr if x < 0])

    best_pair = None
    best_prod = float('-inf')

    # Case 1: Two largest positives
    if len(positives) >= 2:
        prod = positives[0] * positives[1]
        if prod > best_prod:
            best_prod = prod
            best_pair = (positives[1], positives[0])

    # Case 2: Two most negative numbers
    if len(negatives) >= 2:
        prod = negatives[0] * negatives[1]
        if prod > best_prod:
            best_prod = prod
            best_pair = (negatives[1], negatives[0])

    # Case 3: One positive and one negative
    if len(positives) >= 1 and len(negatives) >= 1:
        prod = positives[0] * negatives[0]
        if prod > best_prod:
            best_prod = prod
            best_pair = (negatives[0], positives[0])

    # Fallback for arrays with zeros or single elements
    if best_pair is None and len(arr) >= 2:
        nums = sorted(arr)
        best_prod = max(nums[0] * nums[1], nums[-1] * nums[-2])
        best_pair = (nums[0], nums[1]) if nums[0] * nums[1] > nums[-1] * nums[-2] else (nums[-2], nums[-1])

    return best_pair
