def nCr_mod_p(n, r, p):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    fact = [1] * (p)
    for i in range(1, p):
        fact[i] = fact[i - 1] * i % p

    inv_fact = [1] * (p)
    inv_fact[p - 1] = pow(fact[p - 1], p - 2, p)
    for i in range(p - 2, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p

    def nCr_mod(n_val, r_val):
        if r_val > n_val:
            return 0
        if r_val == 0 or r_val == n_val:
            return 1
        return fact[n_val] * inv_fact[r_val] % p * inv_fact[n_val - r_val] % p

    res = 1
    while n > 0 or r > 0:
        ni = n % p
        ri = r % p
        if ri > ni:
            res = 0
            break
        res = res * nCr_mod(ni, ri) % p
        n //= p
        r //= p

    return res
```

