def rencontres_number(n, m):
    if n < 0 or m < 0:
        return 0
    if m == 0:
        # Derangements of n items: round(n! / e)
        fact = 1
        for i in range(2, n + 1):
            fact *= i
        return round(fact / 2.718281828459045) if n > 0 else 1
    # General case: choose m positions to be fixed, derange the rest
    from math import comb, factorial
    total = 0
    for fixed in range(m + 1):
        remaining = n - fixed
        # derangements of remaining items
        der = 0
        if remaining == 0:
            der = 1
        else:
            f = 1
            for i in range(2, remaining + 1):
                f *= i
            der = round(f / 2.718281828459045) if remaining > 0 else 1
        total += comb(n, fixed) * der
    return total

def rencontres_number(n, m):
    from math import comb
    def derangements(k):
        if k == 0:
            return 1
        d_prev, d_prev2 = 0, 1
        for i in range(2, k + 1):
            d_cur = (i - 1) * (d_prev + d_prev2)
            d_prev, d_prev2 = d_cur, d_prev
        return d_prev
    if m > n:
        return 0
    return comb(n, m) * derangements(n - m)

