def min_Swaps(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        return -1

    mismatches = []
    for i, (c1, c2) in enumerate(zip(s1, s2)):
        if c1 != c2:
            mismatches.append(i)

    n = len(mismatches)
    if n % 2 != 0:
        return -1

    swaps = 0
    i = 0
    while i < n:
        if s1[mismatches[i]] == s1[mismatches[i + 1]]:
            s1 = list(s1)
            s1[mismatches[i]], s1[mismatches[i + 1]] = s1[mismatches[i + 1]], s1[mismatches[i]]
            swaps += 1
            i += 2
        else:
            swaps += 1
            i += 2

    return swaps

